import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  texture,
  uv,
  vec3,
  mix,
  smoothstep,
  clamp,
  dot,
  float,
  fresnel,
  positionLocal,
  normalLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const h = hex.replace('#', '');
  const r = parseInt(h.substring(0, 2), 16) / 255;
  const g = parseInt(h.substring(2, 4), 16) / 255;
  const b = parseInt(h.substring(4, 6), 16) / 255;
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight, PointLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0.45, hex: '#0b0b1000' },
      { at: 1, hex: '#0b0b10eb' },
    ],
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'NOVA ATELIER / GENEVA', role: 'kicker' },
      { text: 'Time, Machined.', role: 'headline' },
      { text: 'Every case begins as a single billet of 904L steel.', role: 'body' },
      { text: 'CALIBRE NA-01 / 72 HOUR RESERVE', role: 'caption' },
    ];

  const root = new Group();
  root.name = 'photo-hero-composite';

  const disposables = [];
  const tweens = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // 1. STAGE BACKDROP (~7x6 at z=-2.5) — vertical gradient, never flat void
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();
  const bgTop = hexToVec3(colors.surface);
  const bgBottom = hexToVec3(colors.background);
  backdropMat.colorNode = mix(bgBottom, bgTop, uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // 2. PHOTO PLATE (parallax-plane, tessellated, depth-displaced)
  // ---------------------------------------------------------------
  const PLATE_W = 4.0;
  const PLATE_H = 2.5;
  const plateGroup = new Group();
  plateGroup.name = 'photo-plate-group';
  plateGroup.position.set(0, 0.1, 0);
  root.add(plateGroup);

  const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H, 64, 64);
  const plateMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.0 });
  // neutral placeholder graph until textures resolve
  plateMat.colorNode = hexToVec3(colors.ink);
  plateMat.emissiveNode = vec3(1, 1, 1).mul(fresnel().mul(0.12));
  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.name = 'photo-plate';
  plateMesh.position.set(0, 0, 0);
  plateGroup.add(plateMesh);
  disposables.push(plateGeo, plateMat);

  const liftColor = hexToVec3('#0d0d12');
  const highlightColor = hexToVec3(colors.paper);
  const DISPLACE_AMPLITUDE = 0.18;

  function configureMaps(colorTex, depthTex) {
    colorTex.colorSpace = THREE.SRGBColorSpace ?? colorTex.colorSpace;
    const colorSample = texture(colorTex, uv());
    let rgb = colorSample.rgb;

    // filmic grade: lift blacks
    rgb = mix(liftColor, rgb, 0.9);
    // midtone contrast +12%
    rgb = rgb.sub(0.5).mul(1.12).add(0.5);
    // highlight shoulder toward paper
    rgb = mix(rgb, highlightColor, smoothstep(0.72, 1.0, rgb));
    // desaturate -8% but preserve red channel
    const lum = dot(rgb, vec3(0.299, 0.587, 0.114));
    const desat = mix(rgb, vec3(lum, lum, lum), 0.08);
    const graded = vec3(clamp(rgb.r, 0.0, 1.0), clamp(desat.g, 0.0, 1.0), clamp(desat.b, 0.0, 1.0));

    plateMat.colorNode = graded;

    const depthSample = texture(depthTex, uv());
    plateMat.positionNode = positionLocal.add(
      normalLocal.mul(depthSample.r.sub(0.5).mul(DISPLACE_AMPLITUDE))
    );

    // rim-of-light silhouette separation (fresnel-based subject separation)
    plateMat.emissiveNode = vec3(1, 1, 1).mul(fresnel().mul(0.18));
    plateMat.needsUpdate = true;
  }

  if (config.imageUrl && config.depthMapUrl) {
    Promise.all([
      ctx.textureLoader.loadTexture(config.imageUrl),
      ctx.textureLoader.loadTexture(config.depthMapUrl),
    ]).then(([colorTex, depthTex]) => {
      disposables.push(colorTex, depthTex);
      configureMaps(colorTex, depthTex);
    });
  }

  // plate mount: opacity 0 -> 1 over 500ms
  plateMat.transparent = true;
  plateMat.opacity = 0;
  const mountTween = gsap.to(plateMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'power2.out',
    delay: 0.02,
  });
  tweens.push(mountTween);

  // idle breathing (single slow transform, <=2%)
  const idleTween = gsap.to(plateGroup.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 4.5,
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut',
  });
  tweens.push(idleTween);

